CREATE TABLE IF NOT EXISTS pok_migrations(version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pok_profile(user_id TEXT PRIMARY KEY REFERENCES user(id) ON DELETE CASCADE,role TEXT NOT NULL DEFAULT 'member',country TEXT,show_country INTEGER NOT NULL DEFAULT 0,locale TEXT NOT NULL DEFAULT 'en',adult_accepted_at INTEGER);
CREATE TABLE IF NOT EXISTS pok_csrf(session_id TEXT PRIMARY KEY REFERENCES session(id) ON DELETE CASCADE,token TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pok_mfa_session(session_id TEXT PRIMARY KEY REFERENCES session(id) ON DELETE CASCADE,verified_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pok_content(id TEXT PRIMARY KEY,author_id TEXT REFERENCES user(id) ON DELETE SET NULL,kind TEXT NOT NULL,parent_id TEXT REFERENCES pok_content(id),title TEXT NOT NULL DEFAULT '',body TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'general',status TEXT NOT NULL DEFAULT 'open',hidden INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS pok_content_list ON pok_content(kind,created_at);
CREATE TABLE IF NOT EXISTS pok_report(id TEXT PRIMARY KEY,reporter_id TEXT REFERENCES user(id) ON DELETE SET NULL,content_id TEXT REFERENCES pok_content(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pok_sanction(id TEXT PRIMARY KEY,target_id TEXT REFERENCES user(id) ON DELETE CASCADE,actor_id TEXT REFERENCES user(id) ON DELETE SET NULL,kind TEXT NOT NULL,reason TEXT NOT NULL,evidence_id TEXT,expires_at INTEGER,revoked_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pok_appeal(id TEXT PRIMARY KEY,sanction_id TEXT REFERENCES pok_sanction(id),user_id TEXT REFERENCES user(id) ON DELETE CASCADE,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pok_block(user_id TEXT REFERENCES user(id) ON DELETE CASCADE,target_id TEXT REFERENCES user(id) ON DELETE CASCADE,PRIMARY KEY(user_id,target_id));
CREATE TABLE IF NOT EXISTS pok_notification(id TEXT PRIMARY KEY,user_id TEXT REFERENCES user(id) ON DELETE CASCADE,kind TEXT NOT NULL,target_id TEXT,body TEXT NOT NULL,seen INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pok_sync(user_id TEXT PRIMARY KEY REFERENCES user(id) ON DELETE CASCADE,revision INTEGER NOT NULL,payload TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pok_dictionary(version INTEGER PRIMARY KEY,payload TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 0,actor_id TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pok_setting(key TEXT PRIMARY KEY,payload TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pok_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT,target_id TEXT,action TEXT NOT NULL,reason TEXT NOT NULL,expires_at INTEGER,created_at INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS pok_audit_no_update BEFORE UPDATE ON pok_audit BEGIN SELECT RAISE(ABORT,'append_only_audit'); END;
CREATE TRIGGER IF NOT EXISTS pok_audit_no_delete BEFORE DELETE ON pok_audit BEGIN SELECT RAISE(ABORT,'append_only_audit'); END;
INSERT OR IGNORE INTO pok_migrations VALUES(1,unixepoch()*1000);
